      "path": "src/cli-workers.mjs",
      "content": "// CLI worker adapter: runs a named worker profile (worker-profiles.mjs) as a\n// child CLI process and folds it into the shared job registry (jobs.mjs), so\n// dsh_worker_status / dsh_worker_result / dsh_worker_cancel work unchanged.\n//\n// Spawning rules (both backends):\n//   - detached: true — the CLI leads its own process group, so cancel/timeout\n//     can SIGTERM (then SIGKILL after a grace period) the whole tree and no\n//     orphan processes survive (e.g. agy's in-process language server).\n//   - env: full process.env passthrough (auth, proxy, GROK_HOME etc.).\n//   - cwd: the caller-provided workspace.\n//   - timeout: a wall timer here kills the group at the deadline; agy\n//     additionally gets --print-timeout = deadline + 15s as a self-exit\n//     backstop in case our timer can never fire.\n//\n// Streams per backend:\n//   agy  — `agy --print <task> --output-format stream-json …` emits NDJSON:\n//          {\"event\":\"init\"} / {\"event\":\"step_update\"} (text_delta + usage while\n//          generating; the liveness signal) / {\"event\":\"result\"} (final response).\n//   grok — `grok -p <task> --output-format streaming-messages-json\n//          --include-partial-messages …` emits NDJSON: {\"type\":\"system\"} init,\n//          {\"type\":\"stream_event\",\"event\":{Anthropic wire event}} deltas\n//          (liveness signal), {\"type\":\"assistant\"} whole message,\n//          {\"type\":\"result\"} final. Usage from \"result\" replaces the per-message\n//          accumulation to avoid double counting.\n//\n// Liveness (\"在动\" vs \"卡死\"): every stream line refreshes activity.lastEventAt.\n// A staleness timer flips liveness to \"stalled\" when no event arrived for\n// STALL_SECONDS while the process is still running (heuristic — a long tool\n// run with a quiet CLI may false-positive, but the process is still alive and\n// job.status stays \"running\"). dsh_worker_status surfaces liveness + activity.\n\nimport { spawn } from 'node:child_process';\nimport { resolve } from 'node:path';\nimport { resolveProfile } from './worker-profiles.mjs';\nimport { registerJob, publishStatus } from './jobs.mjs';\nimport { acquireCwdLock } from './cwd-lock.mjs';\nimport { ORIGIN_CHAIN_ENV, ORIGIN_DEPTH_ENV } from './origin-guard.mjs';\n\nexport const STALL_SECONDS = 120;\nexport const DEFAULT_TIMEOUT_MS = 1_800_000; // matches standalone spawn default\nconst SIGKILL_GRACE_MS = 2_000;\nconst PUBLISH_MIN_INTERVAL_MS = 2_000;\nconst RAW_LINE_CAP = 300; // bounded memory: keep the last N stream lines for debugging\nconst STDERR_TAIL_BYTES = 4_096;\n\nlet nextCliId = 1;\n\n/** SIGTERM the process group, SIGKILL it after a grace period. Never throws. */\nexport function killGroup(child) {\n  try { process.kill(-child.pid, 'SIGTERM'); } catch {}\n  const t = setTimeout(() => {\n    try { process.kill(-child.pid, 'SIGKILL'); } catch {}\n  }, SIGKILL_GRACE_MS);\n  t.unref?.();\n}\n\nfunction usageToTokens(u) {\n  return {\n    input: (u?.input_tokens ?? 0) + (u?.cache_read_input_tokens ?? 0),\n    output: u?.output_tokens ?? 0,\n    reasoning: u?.thinking_tokens ?? 0,\n  };\n}\n\n/** Absolute usage for a backend whose \"result\" event reports session totals. */\nfunction setTokensFromUsage(job, u) {\n  job.tokens = usageToTokens(u);\n}\n\nfunction addTokensFromUsage(job, u) {\n  const t = usageToTokens(u);\n  job.tokens.input += t.input;\n  job.tokens.output += t.output;\n  job.tokens.reasoning += t.reasoning;\n}\n\nfunction buildArgs(profile, task, timeoutMs, effortOverride) {\n  if (profile.backend === 'agy') {\n    const timeoutSec = Math.ceil(timeoutMs / 1000);\n    const args = [\n      '--print', task,\n      '--output-format', 'stream-json',\n      '--dangerously-skip-permissions',\n      '--mode', 'accept-edits',\n      '--print-timeout', `${timeoutSec + 15}s`, // self-exit backstop above our deadline\n    ];\n    if (profile.model) args.push('--model', profile.model);\n    if (effortOverride && profile.effortMap?.[effortOverride]) {\n      args.push('--effort', profile.effortMap[effortOverride]);\n    }\n    return args;\n  }\n  if (profile.backend === 'grok') {\n    const args = [\n      '-p', task,\n      '--output-format', 'streaming-messages-json',\n      '--include-partial-messages',\n      '--permission-mode', 'bypassPermissions',\n    ];\n    if (profile.model) args.push('--model', profile.model);\n    // grok-4.5 is not a reasoning model; no --reasoning-effort even when the\n    // caller passes effort (profile.effortMap === null).\n    return args;\n  }\n  throw new Error(`no CLI adapter for backend \"${profile.backend}\"`);\n}\n\nfunction makeLineHandler(profile, job) {\n  if (profile.backend === 'agy') return handleAgyLine;\n  if (profile.backend === 'grok') return handleGrokLine;\n  throw new Error(`no CLI adapter for backend \"${profile.backend}\"`);\n}\n\nfunction handleAgyLine(job, line, msg) {\n  const ev = msg.event;\n  if (ev === 'init') {\n    job.permissionMode = msg.init?.permission_mode ?? null;\n    job.toolCount = msg.init?.tools?.length ?? 0;\n    return;\n  }\n  if (ev === 'step_update') {\n    const s = msg.step_update ?? {};\n    job.turn = s.step_index ?? job.turn;\n    job.step = (s.step_index ?? 0) + 1;\n    if (s.step_type === 'agent_response' && typeof s.text_delta === 'string') {\n      job._text = (job._text ?? '') + s.text_delta;\n    }\n    if (s.usage) addTokensFromUsage(job, s.usage);\n    return;\n  }\n  if (ev === 'result') {\n    const r = msg.result ?? {};\n    job._agyStatus = r.status ?? null;\n    if (typeof r.response === 'string') job.result = r.response;\n    if (r.usage) setTokensFromUsage(job, r.usage);\n    if (r.status && r.status !== 'SUCCESS') job.error = `agy result status: ${r.status}`;\n    return;\n  }\n  if (ev === 'error') {\n    job.error = msg.error ?? JSON.stringify(msg);\n    return;\n  }\n}\n\nfunction handleGrokLine(job, line, msg) {\n  if (msg.type === 'system' && msg.subtype === 'init') {\n    job.permissionMode = msg.permissionMode ?? null;\n    job.modelUsed = msg.model ?? null;\n    job.toolCount = msg.tools?.length ?? 0;\n    return;\n  }\n  if (msg.type === 'stream_event') {\n    const e = msg.event ?? {};\n    switch (e.type) {\n      case 'message_start': job._msgText = ''; break;\n      case 'content_block_delta': {\n        const d = e.delta ?? {};\n        if (d.type === 'text_delta') job._msgText = (job._msgText ?? '') + d.text;\n        break;\n      }\n      case 'message_delta': {\n        if (e.usage) job._msgUsage = e.usage; // per-message; replaced by totals on result\n        if (e.delta?.stop_reason) job._stopReason = e.delta.stop_reason;\n        break;\n      }\n    }\n    return;\n  }\n  if (msg.type === 'assistant' && msg.message) {\n    const m = msg.message;\n    const text = (m.content ?? [])\n      .filter((c) => c?.type === 'text').map((c) => c.text).join('');\n    if (text) job._msgText = text; // last whole message = the final answer\n    if (m.usage) job._msgUsage = m.usage;\n    if (m.stop_reason) job._stopReason = m.stop_reason;\n    return;\n  }\n  if (msg.type === 'result') {\n    job._grokIsError = !!msg.is_error;\n    if (typeof msg.result === 'string') job.result = msg.result;\n    if (msg.usage) setTokensFromUsage(job, msg.usage); // totals win over message sums\n    if (msg.is_error) {\n      job.error = String(msg.errors?.[0] ?? `grok result error (${msg.subtype})`).slice(0, 400);\n    }\n    return;\n  }\n  if (msg.type === 'error') {\n    job.error = msg.error?.message ?? JSON.stringify(msg.error);\n    return;\n  }\n}\n\nfunction touchActivity(job) {\n  const now = Date.now();\n  job.activity.events += 1;\n  job.activity.lastEventAt = new Date(now).toISOString();\n  job.liveness = 'active';\n  clearTimeout(job._stallTimer);\n  job._stallTimer = setTimeout(() => {\n    if (job.status !== 'running') return;\n    job.liveness = 'stalled';\n    publishStatus();\n  }, STALL_SECONDS * 1000);\n  job._stallTimer.unref?.();\n  if (now - (job._lastPublishAt ?? 0) >= PUBLISH_MIN_INTERVAL_MS) {\n    job._lastPublishAt = now;\n    publishStatus();\n  }\n}\n\nfunction settle(job, { status, error, stopReason }) {\n  if (job._settled) return;\n  job._settled = true;\n  // Release the cwd lock on EVERY terminal path: exit (done/failed), spawn\n  // error, timeout kill, cancel — all settle through here (WPC9).\n  job._releaseCwdLock?.();\n  job._releaseCwdLock = null;\n  clearTimeout(job._timer);\n  clearTimeout(job._stallTimer);\n  if (job.status === 'cancelled') {\n    job.stopReason ??= 'cancelled';\n  } else {\n    job.status = status;\n    if (error !== undefined) job.error = job.error ?? error;\n    if (stopReason !== undefined) job.stopReason = job.stopReason ?? stopReason;\n  }\n  job.endedAt = new Date().toISOString();\n  publishStatus();\n  for (const w of job.waiters.splice(0)) w();\n}\n\nexport async function startCliJob({ worker, task, cwd, timeoutMs = DEFAULT_TIMEOUT_MS, source = 'api', effort, origin = null, allowConcurrentCwd = false }) {\n  const profile = typeof worker === 'string' ? resolveProfile(worker) : worker;\n  const workspace = resolve(cwd ?? process.cwd());\n  const args = buildArgs(profile, task, timeoutMs, effort);\n  const id = `cli-${nextCliId++}-${Date.now().toString(36)}`;\n  const startedAt = new Date().toISOString();\n\n  // Cwd advisory lock BEFORE the child spawns: a conflicting dispatch is\n  // refused with the holder info (WPC9). The lock is released by settle(),\n  // which every terminal path passes through.\n  let releaseLock = null;\n  if (!allowConcurrentCwd) {\n    releaseLock = acquireCwdLock({ cwd: workspace, jobId: id, backend: profile.backend, mode: 'cli', startedAt }).release;\n  }\n\n  const job = {\n    id,\n    backend: profile.backend,\n    profile: profile.name,\n    mode: 'cli',\n    tier: profile.name, // display: profile name rides the tier column\n    model: profile.model ?? '(cli default)',\n    effort: (effort && profile.effortMap?.[effort]) ?? profile.effort ?? null,\n    task, source, cwd: workspace,\n    status: 'running', turn: 0, step: 0, currentTool: null, toolCalls: 0,\n    tokens: { input: 0, output: 0, reasoning: 0 },\n    startedAt, endedAt: null,\n    origin_depth: origin?.depth ?? null, origin_chain: origin?.chain ?? null,\n    result: null, error: null, stopReason: null,\n    activity: { events: 0, lastEventAt: null },\n    liveness: 'starting',\n    waiters: [],\n    permissionMode: null, modelUsed: null, toolCount: null,\n    _text: '', _msgText: '', _msgUsage: null, _stopReason: null,\n    _agyStatus: null, _grokIsError: false,\n    _rawLines: [], _stderrTail: '',\n    _timer: null, _stallTimer: null, _lastPublishAt: 0, _settled: false,\n    _releaseCwdLock: releaseLock,\n  };\n  try {\n    registerJob(job);\n  } catch (err) {\n    releaseLock?.();\n    throw err;\n  }\n\n  let child;\n  try {\n    child = spawn(profile.cli, args, {\n      cwd: workspace,\n      // Origin guard: the CLI worker inherits the dispatch chain, so a crew\n      // instance it starts itself continues the chain (WPC9).\n      env: {\n        ...process.env,\n        ...(origin ? { [ORIGIN_CHAIN_ENV]: JSON.stringify(origin.chain), [ORIGIN_DEPTH_ENV]: String(origin.depth) } : {}),\n      },\n      detached: true,\n      stdio: ['ignore', 'pipe', 'pipe'],\n    });\n  } catch (err) {\n    // spawn() throws synchronously only for malformed options; settle the job\n    // so it does not linger as 'running' with no process behind it.\n    settle(job, {\n      status: 'failed',\n      error: `could not spawn \"${profile.cli}\": ${err?.message ?? err}`,\n      stopReason: 'spawn-failed',\n    });\n    return job;\n  }\n  job.pid = child.pid;\n  // Positive process-group id (detached spawn ⇒ pgid === pid); kill(-pgid)\n  // signals the whole group. WPC14: the panel/proc-kill endpoint reads this\n  // from job views and shard mirrors to offer killing an orphaned worker.\n  job.pgid = child.pid;\n  // cancelJob() in jobs.mjs calls job.harness.close() — same interface as the\n  // standalone DSH harness.\n  job.harness = { child, close: async () => killGroup(child) };\n\n  job._timer = setTimeout(() => {\n    if (job.status !== 'running') return;\n    // Mark failed immediately so dsh_worker_status shows the timeout during\n    // the 0-2 s kill window; settle() finalizes endedAt/waiters on exit.\n    job.status = 'failed';\n    job.stopReason = 'timeout';\n    job.error = `timed out after ${Math.round(timeoutMs / 1000)}s (CLI process group killed)`;\n    job.liveness = 'stalled';\n    publishStatus();\n    killGroup(child);\n    job._timedOut = true;\n  }, timeoutMs);\n\n  const handleLine = makeLineHandler(profile, job);\n  let buf = '';\n  child.stdout.on('data', (chunk) => {\n    buf += chunk.toString();\n    let i;\n    while ((i = buf.indexOf('\\n')) >= 0) {\n      const line = buf.slice(0, i).trim();\n      buf = buf.slice(i + 1);\n      if (!line) continue;\n      job._rawLines.push(line.slice(0, 500));\n      if (job._rawLines.length > RAW_LINE_CAP) job._rawLines.splice(0, job._rawLines.length - RAW_LINE_CAP);\n      touchActivity(job);\n      // Once failed/cancelled/timed-out, ignore what the dying process still\n      // writes: its final error events must not overwrite the timeout/cancel\n      // error we already recorded.\n      if (job.status !== 'running') continue;\n      try {\n        handleLine(job, line, JSON.parse(line));\n      } catch {\n        // Non-JSON stdout line (banner, stray output): keep as evidence, no parse.\n      }\n    }\n  });\n  child.stderr.on('data', (chunk) => {\n    job._stderrTail = (job._stderrTail + chunk.toString()).slice(-STDERR_TAIL_BYTES);\n  });\n\n  child.on('error', (err) => {\n    settle(job, {\n      status: 'failed',\n      error: `could not spawn \"${profile.cli}\": ${err?.message ?? err} — is it installed and on PATH?`,\n      stopReason: 'spawn-failed',\n    });\n  });\n\n  child.on('exit', (code, signal) => {\n    const timedOut = job._timedOut === true;\n    if (job.status === 'running') {\n      if (timedOut) {\n        settle(job, { status: 'failed', stopReason: 'timeout' });\n      } else if (job._agyStatus && job._agyStatus !== 'SUCCESS') {\n        settle(job, { status: 'failed', stopReason: job._agyStatus });\n      } else if (job._grokIsError) {\n        settle(job, { status: 'failed', stopReason: 'error' });\n      } else if (job.result != null && code === 0) {\n        job.stopReason = job._stopReason ?? 'completed';\n        settle(job, { status: 'done', stopReason: job.stopReason });\n      } else if (job.result != null && code !== 0) {\n        settle(job, {\n          status: 'failed',\n          stopReason: job._stopReason ?? `exit code ${code}`,\n          error: job._stderrTail.trim().slice(-400) || `CLI exited with code ${code}`,\n        });\n      } else if (code === 0) {\n        // Stream ended without a result event: fall back to accumulated text\n        // and the last per-message usage we saw.\n        job.result = job._text ?? job._msgText ?? '';\n        if (job._msgUsage) addTokensFromUsage(job, job._msgUsage);\n        job.stopReason = job._stopReason ?? 'completed';\n        settle(job, { status: 'done', stopReason: job.stopReason });\n      } else {\n        settle(job, {\n          status: 'failed',\n          stopReason: `exit code ${code}${signal ? ` (signal ${signal})` : ''}`,\n          error: job._stderrTail.trim().slice(-400) || `CLI exited with code ${code}`,\n        });\n      }\n    } else {\n      settle(job, { status: job.status }); // cancelled path: keep the cancellation\n    }\n  });\n\n  return job;\n}\n"
    },
    {
      "path": "src/cwd-lock.mjs",
      "content": "// Advisory per-cwd concurrency lock (WPC9 guardrail 2).\n//\n// Real incident (2026-08-2x): two workers writing the same repo at once left\n// another process reading a half-written file (939 lines, unparseable). As\n// the backend matrix (hub / standalone / agy / grok / ...) grows, concurrent\n// same-repo workers stop being an edge case, so the dispatcher now REFUSES a\n// second running job for one cwd instead of queueing it: queueing would hide\n// the caller bug (\"you should not have dispatched two writers at one repo\")\n// behind a silent wait, and a second writer usually corrupts whatever the\n// first one is doing anyway.\n//\n// Scope and lifetime:\n//   - Keyed by the canonical absolute path of the cwd — realpath when the\n//     directory exists (symlink aliases like macOS's /tmp -> /private/tmp\n//     then share one lock), resolve() otherwise.\n//   - Process memory only, on purpose: no file locks, so a crashed dispatch\n//     process can never leave a permanent deadlock behind — its locks die\n//     with it. Locks therefore coordinate dispatches within one crew MCP\n//     session (one per host session).\n//   - Advisory: allow_concurrent_cwd: true skips acquisition entirely\n//     (read-only fan-out over one repo is legitimate).\n//   - Released on every terminal path (done / failed / cancelled / timeout)\n//     through the job settle hooks: jobs.mjs startJob finally (standalone)\n//     and cli-workers settle (CLI). Hub jobs have no settle callback on the\n//     client, so their locks are released when a settled state is observed\n//     (hub.get after wait, dsh_worker_status purge, stale-check on acquire).\n\nimport { resolve } from 'node:path';\nimport { realpathSync } from 'node:fs';\n\nconst locks = new Map(); // canonical cwd -> holder\n\n/** Canonical absolute path of a workspace cwd (realpath when it exists). */\nexport function normalizeCwd(cwd) {\n  try { return realpathSync.native(String(cwd)); } catch { return resolve(String(cwd)); }\n}\n\n/** Thrown by acquireCwdLock when another running job holds the cwd. */\nexport class CwdLockError extends Error {\n  constructor(holder) {\n    super(\n      `workspace \"${holder.cwd}\" is already held by a running worker (job ${holder.jobId}, backend ${holder.backend}, mode ${holder.mode}, started at ${holder.startedAt}). ` +\n      'Refusing this dispatch instead of queueing it: two workers writing the same repo concurrently corrupt files. ' +\n      'Wait for that job to settle, cancel it, or pass allow_concurrent_cwd: true if this task is read-only.',\n    );\n    this.name = 'CwdLockError';\n    this.holder = { ...holder };\n  }\n}\n\n/**\n * Acquire the advisory lock for one cwd. Returns { holder, release } where\n * release() is idempotent and safe to call from any settle path. With\n * allowConcurrent: true this is a deliberate no-op (the lock stays advisory).\n */\nexport function acquireCwdLock({ cwd, jobId, backend, mode, startedAt, allowConcurrent = false }) {\n  if (allowConcurrent) return { holder: null, release() {} };\n  const key = normalizeCwd(cwd);\n  const existing = locks.get(key);\n  if (existing) throw new CwdLockError(existing);\n  const holder = { jobId, backend, mode, startedAt, cwd: key };\n  locks.set(key, holder);\n  let released = false;\n  return {\n    holder,\n    release() {\n      if (released) return;\n      released = true;\n      if (locks.get(key) === holder) locks.delete(key);\n    },\n  };\n}\n\n/** Backfill the real job id after a spawn whose id was unknown at acquire time (hub path). */\nexport function updateCwdLockHolder({ cwd, jobId }) {\n  const holder = locks.get(normalizeCwd(cwd));\n  if (holder) holder.jobId = jobId;\n}\n\n/** Release whichever lock the given job holds (idempotent). */\nexport function releaseCwdLockByJobId(jobId) {\n  for (const [key, holder] of locks) {\n    if (holder.jobId === jobId) { locks.delete(key); return true; }\n  }\n  return false;\n}\n\n/** Current lock table for dsh_worker_status: which cwd is held by whom. */\nexport function getCwdLocks() {\n  return [...locks.entries()].map(([cwd, holder]) => ({ cwd, holder: { ...holder } }));\n}\n"
    },
    {
      "path": "src/hub-client.mjs",
      "content": "// Client for the in-host workers-hub jobs API. When a DSH web instance with the\n// dsh-crew bundle is running, jobs run inside it (sessions visible in the\n// Web UI); otherwise the MCP server falls back to standalone runtimes.\n\nimport { readGlobalConfig } from './install/install.mjs';\nimport { pluginEnv } from './plugin-env.mjs';\n\nconst BASE = (pluginEnv('CREW_HUB') ?? readGlobalConfig().hub_url).replace(/\\/$/, '');\nconst API = `${BASE}/_dsh/dsh-crew`;\n\nlet lastProbe = { at: 0, ok: false };\n\nexport async function hubAvailable() {\n  if (Date.now() - lastProbe.at < 10_000) return lastProbe.ok;\n  try {\n    const res = await fetch(`${API}/ping`, { signal: AbortSignal.timeout(800) });\n    const body = await res.json();\n    lastProbe = { at: Date.now(), ok: res.ok && body?.service === 'dsh-crew-hub' };\n  } catch {\n    lastProbe = { at: Date.now(), ok: false };\n  }\n  return lastProbe.ok;\n}\n\nasync function call(path, init) {\n  const res = await fetch(`${API}${path}`, init);\n  const body = await res.json();\n  if (!res.ok || body.ok === false) throw new Error(body.error ?? `hub request failed (${res.status})`);\n  return body;\n}\n\n/**\n * One long-poll may never outlive the runtime's request timeouts. Node's\n * fetch (undici) aborts a request whose response headers have not arrived\n * within 300 s, and the hub sends nothing until the job settles — so a\n * `?wait=2700` poll dies at five minutes with a bare \"fetch failed\" while the\n * job keeps running server-side. Measured on 2026-08-19: dispatches of 2 s and\n * 4 m 03 s returned normally; 14 m, 22 m, 35 m and 41 m all failed that way.\n * Slicing the wait keeps every individual request short enough that no\n * runtime, proxy or load balancer can cut it.\n */\nconst MAX_POLL_SLICE_SECONDS = 60;\n\nexport const hub = {\n  probe: (binding) => call('/worker-probe', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(binding) }).then(b => b.result),\n  spawn: (spec) => call('/jobs', {\n    method: 'POST',\n    headers: { 'content-type': 'application/json' },\n    body: JSON.stringify(spec),\n  }).then((b) => b.job),\n  list: () => call('/jobs').then((b) => b.jobs),\n  // The LLM routes the HOST has configured. Only the hub can answer this: the\n  // MCP server is a separate process with no ctx.llm. Returns [] rather than\n  // throwing when the hub is too old to serve the route, so a stale hub\n  // degrades to \"cannot enumerate\" instead of breaking the config tool.\n  providers: () => call('/providers').then((b) => ({\n    providers: b.providers ?? [],\n    bindings: b.bindings ?? null,\n  })).catch(() => ({ providers: [], bindings: null })),\n  // `waitSeconds = 0` keeps the plain \"read it now\" semantics; anything longer\n  // is served by repeated short waits until the job settles or the budget ends.\n  get: async (id, waitSeconds = 0) => {\n    const deadline = Date.now() + waitSeconds * 1000;\n    for (;;) {\n      const remaining = Math.ceil((deadline - Date.now()) / 1000);\n      const slice = waitSeconds <= 0 ? 0 : Math.max(1, Math.min(MAX_POLL_SLICE_SECONDS, remaining));\n      const job = await call(`/jobs/${id}?wait=${slice}`).then((b) => b.job);\n      if (job.status !== 'running' || waitSeconds <= 0 || Date.now() >= deadline) return job;\n    }\n  },\n  cancel: (id) => call(`/jobs/${id}/cancel`, { method: 'POST' }).then((b) => b.job),\n};\n"
    },
    {
      "path": "src/hub/index.mjs",
      "content": "// DSH host plugin: workers-hub.\n// Runs DeepSeek workers as first-class in-host agent sessions (visible in the\n// Web UI session list), exposes a loopback jobs API for the CC/Codex MCP shim,\n// and serves the one-click installer endpoints for the settings page.\n\nimport { randomUUID } from 'node:crypto';\nimport { join } from 'node:path';\nimport { homedir } from 'node:os';\nimport { isAbsoluteCwd, canonicalCwd } from '../paths.mjs';\nimport { createShardWriter, readMergedStatus } from '../status-shard.mjs';\nimport { procAlive, killWorkerProcess, parsePid, ProcKillRefused } from '../proc-kill.mjs';\nimport { installWorkerQuestionHandoff } from '../worker-question.mjs';\nimport { probeProvider } from '../provider-probe.mjs';\n\n// No @deepseek-ai imports here on purpose: this plugin is loaded into the\n// profile realm, and importing our own package copies would create duplicate\n// module realms (symbol identity mismatches in the tool runtime). Everything\n// below is either plain data or inlined logic that only touches ctx APIs.\n\n/** Inlined from @deepseek-ai/dsh-agent model-selection.ts (same semantics). */\nfunction installModelSelection(agentCtx, selection) {\n  agentCtx.on('system-prompt/assemble', async (_assembly, _cause, next) => {\n    const selected = selection.current;\n    const assembled = await next();\n    selection.assembled = selected;\n    if (selected === undefined) return assembled;\n    return { ...assembled, variables: { ...assembled.variables, provider: selected.provider, model: selected.model } };\n  });\n  agentCtx.on('agent/request', async (_payload, next) => {\n    const resolved = await next();\n    const selected = selection.assembled;\n    if (selected === undefined) return resolved;\n    const { reasoningEffort: _inherited, ...rest } = resolved;\n    return {\n      ...rest, provider: selected.provider, model: selected.model,\n      ...(selected.reasoningEffort === undefined ? {} : { reasoningEffort: selected.reasoningEffort }),\n    };\n  });\n}\n\n/** Inlined shape of createUserMessage (role + fresh id, frozen). */\nfunction userMessage(text) {\n  return Object.freeze({\n    id: randomUUID(),\n    role: 'user',\n    content: [{ type: 'text', text }],\n    source: { kind: 'user' },\n  });\n}\n\n/**\n * The rejection a worker's ask_user_question receives. Shaped like the host's\n * UserQuestionError (name + code) so the seam restores it as one and the\n * model sees the message, the same way the host answers a question from a\n * child agent that has no human either (DELEGATED_CALLER).\n */\nexport function unattendedQuestion() {\n  const error = new Error(\n    'no one is attending this dsh-crew worker session, so a question cannot be answered and must not be waited on. '\n    + 'Stop and put the unresolved question in your final message so the orchestrator can obtain the required answer or approval. '\n    + 'An unanswered question grants no permission; never select an option automatically.',\n  );\n  error.name = 'UserQuestionError';\n  error.code = 'UNATTENDED_WORKER';\n  return error;\n}\n\nexport const name = 'dsh-crew';\nexport const inject = ['agents', 'sessions', 'agentDefaultModel', 'tools', 'llm', 'attachments'];\n\n// Optional: the host's durable locale preference seeds server-side strings\n// before the panel is ever opened. Absent preference means \"browser decides\".\nfunction seedLangFromHost(ctx) {\n  try {\n    const pref = ctx.settings?.get?.('locale')?.preference;\n    if (pref) setLang(pref);\n  } catch { /* settings service absent or shaped differently — keep the default */ }\n}\n\nimport { setLang } from '../i18n.mjs';\n\nconst ROUTE_BASE = '/_dsh/dsh-crew';\n// Tier -> {provider, model}. The defaults live in tier-binding.mjs; the\n// caller may override per dispatch, and the hub's own config is the fallback\n// when it does not (the same shape the preset lookup below uses).\nimport { describeBindings, resolveTierBinding, TIERS } from '../tier-binding.mjs';\nconst CONFIG_DIR = join(homedir(), '.config', 'dsh-crew');\n\n// ---------- job registry ----------\n\n/** Bounded task preview with a visible truncation marker (PATTERN-AUDIT D3:\n// a silently truncated task reads like the whole brief in status views). */\nfunction clipTask(task, cap = 300) {\n  return task.length > cap ? task.slice(0, cap) + '…' : task;\n}\n\nexport class WorkerRegistry {\n  constructor(ctx, shard = createShardWriter('hub')) {\n    this.ctx = ctx;\n    this.jobs = new Map();\n    this.nextId = 1;\n    this.shard = shard;\n  }\n\n  view(job, withResult = false) {\n    const v = {\n      id: job.id, sessionId: job.sessionId, tier: job.tier, model: job.model, provider: job.provider,\n      effort: job.effort, status: job.status, source: job.source, task: clipTask(job.task),\n      cwd: job.cwd, turn: job.turn, step: job.step, currentTool: job.currentTool,\n      toolCalls: job.toolCalls, tokens: job.tokens, mode: 'hub',\n      startedAt: job.startedAt, endedAt: job.endedAt,\n      ...(job.questions === undefined ? {} : { questions: job.questions }),\n    };\n    if (withResult) {\n      v.result = job.result; v.error = job.error; v.stopReason = job.stopReason;\n      v.reasonDetail = job.reasonDetail;\n    }\n    return v;\n  }\n\n  publish() {\n    this.shard.publish([...this.jobs.values()].map((j) => this.view(j)));\n  }\n\n  async spawn({ task, tier = 'flash', effort = 'max', cwd, source = 'api', provider, model, preset }) {\n    if (!TIERS.includes(tier)) throw new Error(`unknown tier \"${tier}\"`);\n    // An explicit {provider, model} from the caller wins (the MCP process owns\n    // session-level overrides, exactly as it does for presets); otherwise the\n    // hub's own stored config decides, and failing that the tier default.\n    const bound = resolveTierBinding(tier, this.getConfig?.() ?? {});\n    const resolvedProvider = typeof provider === 'string' && provider.trim() !== '' ? provider.trim() : bound.provider;\n    const resolvedModel = typeof model === 'string' && model.trim() !== '' ? model.trim() : bound.model;\n    if (!['off', 'high', 'max'].includes(effort)) throw new Error(`unknown effort \"${effort}\"`);\n    // Accept POSIX, Windows drive (D:\\x, C:/x) and UNC (\\\\srv\\share) roots.\n    if (!isAbsoluteCwd(cwd)) throw new Error('cwd must be an absolute path');\n    // One canonical form for the job, the advisory lock and the workspace\n    // lookup: D:/x and D:\\x must map to the same workspace on Windows.\n    const cwdPath = canonicalCwd(cwd);\n    await this.ctx.get('loader')?.await();\n\n    const id = `hub-${this.nextId++}-${Date.now().toString(36)}`;\n    const sessionId = `session-${randomUUID()}`;\n    const job = {\n      id, sessionId, tier, model: resolvedModel, provider: resolvedProvider, effort, task, source, cwd: cwdPath,\n      status: 'running', turn: 0, step: 0, currentTool: null, toolCalls: 0,\n      tokens: { input: 0, output: 0, reasoning: 0 },\n      startedAt: new Date().toISOString(), endedAt: null,\n      result: null, error: null, stopReason: null, handle: null, waiters: [],\n      texts: [],\n    };\n    this.jobs.set(id, job);\n\n    const selection = { provider: resolvedProvider, model: resolvedModel, reasoningEffort: effort };\n    const presets = this.ctx.get('agentPresets');\n    const cfg = this.getConfig?.() ?? {};\n    const wanted = preset ?? (tier === 'flash' ? cfg.preset_flash : cfg.preset_pro);\n    const presetId = presets === undefined\n      ? undefined\n      : (await presets.resolve(!wanted || wanted === 'default' ? undefined : wanted)).id;\n\n    const onEvent = (session, event) => {\n      switch (event.type) {\n        case 'step/start':\n          job.turn = event.data?.turn ?? job.turn;\n          job.step = event.data?.step ?? job.step;\n          break;\n        case 'tool/call': job.currentTool = event.data?.name ?? null; job.toolCalls += 1; break;\n        case 'tool/result': job.currentTool = null; break;\n        case 'assistant/message': {\n          const u = event.data?.usage;\n          if (u) {\n            job.tokens.input += u.inputTokens ?? 0;\n            job.tokens.output += u.outputTokens ?? 0;\n            job.tokens.reasoning += u.reasoningTokens ?? 0;\n          }\n          const text = (event.data?.message?.content ?? [])\n            .filter((c) => c?.type === 'text').map((c) => c.text).join('');\n          if (text) job.texts.push(text);\n          break;\n        }\n        case 'turn/end':\n          job.stopReason = event.data?.reason?.kind ?? null;\n          job.reasonDetail = event.data?.reason;\n          break;\n      }\n      this.publish();\n    };\n\n    const run = async () => {\n      const handle = await this.ctx.agents.create({\n        sessionId,\n        meta: { cwd: cwdPath, ...(presetId === undefined ? {} : { agentPreset: presetId }) },\n        agentOptions: { provider: selection.provider, model: selection.model },\n        setup: async (agentCtx) => {\n          installModelSelection(agentCtx, { current: selection, assembled: undefined });\n          if (presets !== undefined) await presets.mount(agentCtx, presetId);\n          // Nobody attends a worker session, so a question would wait forever\n          // (#13). Claim this agent's requests ahead of the Web answerer.\n          installWorkerQuestionHandoff(agentCtx, job, () => this.publish());\n          agentCtx.on('session/event', onEvent);\n          agentCtx.on('agent/error', (payload) => {\n            const err = payload?.error;\n            if (job.status !== 'needs_input') job.error = err?.message ?? String(err);\n          });\n        },\n      });\n      job.handle = handle;\n      if (job.status === 'needs_input') { await handle.dispose(); return; }\n      try {\n        // Group the worker session under the workspace of its cwd; create the\n        // workspace when none exists yet (resolveByPath is exact-match, so a\n        // job cwd never inherits a parent directory's workspace).\n        const registry = this.ctx.get('workspaceRegistry');\n        if (registry !== undefined) {\n          const ws = (await registry.resolveByPath(cwdPath)) ?? (await registry.create(cwdPath));\n          await ws.attachSession(sessionId);\n        }\n      } catch (err) {\n        this.ctx.logger?.warn?.(`dsh-crew: workspace attach failed for ${cwdPath}: ${err?.message ?? err}`);\n      }\n      await handle.agent.whenIdle();\n      handle.agent.followup(userMessage(task));\n      await handle.agent.whenIdle();\n      if (job.status !== 'needs_input') {\n        job.result = job.texts.at(-1) ?? '';\n        job.status = job.stopReason === 'completed' ? 'done' : 'failed';\n      }\n      if (job.status === 'failed' && !job.error) job.error = `turn ended: ${job.stopReason ?? 'unknown'}`;\n      await this.ctx.sessions.flush(handle.agent.session);\n    };\n\n    job.promise = run()\n      .catch((err) => {\n        if (job.status === 'running') job.status = 'failed';\n        job.error = job.error ?? (err?.message ?? String(err));\n      })\n      .finally(() => {\n        job.endedAt = new Date().toISOString();\n        job.currentTool = null;\n        this.publish();\n        for (const w of job.waiters.splice(0)) w();\n      });\n\n    this.publish();\n    return job;\n  }\n\n  async wait(id, timeoutMs) {\n    const job = this.jobs.get(id);\n    if (!job) return undefined;\n    if (job.status !== 'running') return job;\n    await Promise.race([\n      new Promise((res) => job.waiters.push(res)),\n      timeoutMs > 0 ? new Promise((res) => setTimeout(res, timeoutMs)) : Promise.resolve(),\n    ]);\n    return job;\n  }\n\n  async cancel(id) {\n    const job = this.jobs.get(id);\n    if (!job) return undefined;\n    if (job.status === 'running') {\n      job.status = 'cancelled';\n      job.error = 'cancelled by request';\n      try { await job.handle?.dispose(); } catch {}\n      this.publish();\n    }\n    return job;\n  }\n\n  async dispose() {\n    for (const job of this.jobs.values()) {\n      if (job.status === 'running') { try { await job.handle?.dispose(); } catch {} }\n    }\n  }\n}\n\n// ---------- loopback route helpers (pattern from dsh-noema) ----------\n\nfunction isIpv4Loopback(a) { return /^127(\\.\\d{1,3}){3}$/.test(a); }\nfunction isLoopbackAddress(address) {\n  if (!address) return false;\n  const n = address.toLowerCase().split('%', 1)[0];\n  if (n === '::1' || isIpv4Loopback(n)) return true;\n  if (!n.startsWith('::ffff:')) return false;\n  return isIpv4Loopback(n.slice(7));\n}\nfunction isLoopbackRequest(req) {\n  if (!isLoopbackAddress(req.socket?.remoteAddress)) return false;\n  const host = (req.headers.host ?? '').split(':')[0].toLowerCase();\n  return host === 'localhost' || host === '127.0.0.1' || host === '[::1]' || isIpv4Loopback(host);\n}\nfunction sendJson(res, status, value, headers = {}) {\n  const body = JSON.stringify(value);\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': Buffer.byteLength(body),\n    'cache-control': 'no-store',\n    'x-content-type-options': 'nosniff',\n    'cross-origin-resource-policy': 'same-origin',\n    ...headers,\n  });\n  res.end(body);\n}\n/**\n * The panel is the authority on the active locale (DSH's setting may be unset,\n * leaving it to the browser), so it tags requests with ?lang= / body.lang and\n * the hub adopts it. Conversation-side paths with no request behind them —\n * pasted-image transcription — then follow the same language.\n */\nfunction adoptLang(value) {\n  if (value === 'zh' || value === 'en') setLang(value);\n}\n\n/**\n * `?wait` as a non-negative integer second count. Absent/empty means 0;\n * anything non-numeric, fractional or negative is null (HTTP 400) — a\n * garbage wait must be an error, never a silent no-wait (PATTERN-AUDIT D2:\n * `?wait=abc` used to return immediately with 200 OK because\n * Math.min(NaN, 600) is NaN and the wait promise resolved instantly).\n */\nexport function parseWaitSeconds(value) {\n  if (value === undefined || value === null || value === '') return 0;\n  if (!/^\\d+$/.test(String(value))) return null;\n  const n = Number(value);\n  if (!Number.isSafeInteger(n)) return null;\n  return n;\n}\n\nasync function readBody(req, limit = 64 * 1024) {\n  let body = '';\n  for await (const chunk of req) {\n    body += chunk;\n    if (body.length > limit) throw new Error('payload too large');\n  }\n  return body.trim() === '' ? {} : JSON.parse(body);\n}\n\n// ---------- plugin entry ----------\n\nexport async function apply(ctx) {\n  seedLangFromHost(ctx);\n  const hub = new WorkerRegistry(ctx);\n  try {\n    const { readGlobalConfig } = await import('../install/install.mjs');\n    hub.getConfig = () => readGlobalConfig();\n  } catch {}\n  const disposers = [];\n\n  // Multimodal bridge: register describe_image / generate_image for the DS\n  // model. Config is read per call so settings-page edits apply live.\n  try {\n    const { createMultimodalTools } = await import('../multimodal.mjs');\n    const { readGlobalConfig } = await import('../install/install.mjs');\n    for (const tool of createMultimodalTools(() => readGlobalConfig())) {\n      disposers.push(ctx.effect(() => ctx.tools.register(tool), `dsh-crew: ${tool.name} tool`));\n    }\n  } catch (err) {\n    ctx.logger?.warn?.(`dsh-crew: multimodal tools unavailable: ${err?.message ?? err}`);\n  }\n\n  // Vision route: image paste on the text-only DS models (admission adapter +\n  // pre-step transcription).\n  try {\n    const { installVisionRoute } = await import('../vision-route.mjs');\n    const { readGlobalConfig } = await import('../install/install.mjs');\n    disposers.push(installVisionRoute(ctx, () => readGlobalConfig()));\n  } catch (err) {\n    ctx.logger?.warn?.(`dsh-crew: vision route unavailable: ${err?.message ?? err}`);\n  }\n\n  ctx.inject(['webServer'], (webCtx) => {\n    const webServer = webCtx.webServer;\n    const disposers = [];\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/worker-probe`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'POST only' }, { allow: 'POST' });\n        if (!(req.headers['content-type'] ?? '').toLowerCase().startsWith('application/json')) return sendJson(res, 415, { ok: false, error: 'application/json required' });\n        try {\n          const body = await readBody(req);\n          if (typeof body.provider !== 'string' || body.provider.trim() === '' || typeof body.model !== 'string' || body.model.trim() === '') return sendJson(res, 400, { ok: false, error: 'provider and model required' });\n          const result = await probeProvider(ctx.llm, { provider: body.provider.trim(), model: body.model.trim() });\n          return sendJson(res, 200, { ok: true, result });\n        } catch { return sendJson(res, 400, { ok: false, error: 'invalid probe request' }); }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/ping`,\n      handler: (req, res) => sendJson(res, 200, { ok: true, service: 'dsh-crew-hub' }),\n    }));\n\n    // WPC14: liveness probe for a ghost job's recorded pid. The panel probes\n    // orphaned tombstones that carry a pid so it can offer the \"process still\n    // alive\" badge and a kill button; same process.kill(pid, 0) probe the\n    // status shard uses for writer liveness (status-shard.mjs writerProcessAlive).\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/proc-alive`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        if (req.method !== 'GET') return sendJson(res, 405, { ok: false, error: 'GET only' }, { allow: 'GET' });\n        try {\n          const url = new URL(req.url, 'http://localhost');\n          const pid = parsePid(url.searchParams.get('pid'));\n          if (pid === null) return sendJson(res, 400, { ok: false, error: 'pid must be a positive integer' });\n          return sendJson(res, 200, { ok: true, alive: procAlive(pid) });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    // WPC14: verified kill of a ghost job's recorded pid. The pid may have\n    // been recycled since the job died, so the command line is read (ps) and\n    // must match a process shape this plugin spawns (DSH runtime / agy /\n    // grok) before anything is signalled; then SIGTERM (whole group when a\n    // pgid is given) and SIGKILL after a ~3s grace. Refusals are readable,\n    // in the origin-guard style.\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/proc-kill`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'POST only' }, { allow: 'POST' });\n        try {\n          const body = await readBody(req);\n          adoptLang(body?.lang);\n          const pid = parsePid(body?.pid);\n          if (pid === null) return sendJson(res, 400, { ok: false, error: 'pid must be a positive integer' });\n          let pgid = null;\n          if (body.pgid !== undefined && body.pgid !== null) {\n            pgid = parsePid(body.pgid);\n            if (pgid === null) return sendJson(res, 400, { ok: false, error: 'pgid must be a positive integer' });\n          }\n          const result = await killWorkerProcess({ pid, pgid });\n          return sendJson(res, 200, { ok: true, ...result });\n        } catch (err) {\n          if (err instanceof ProcKillRefused) {\n            return sendJson(res, 403, { ok: false, error: err.message, code: err.code, pid: err.pid ?? null, command: err.command ?? null });\n          }\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'prefix', path: `${ROUTE_BASE}/jobs`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        try {\n          const url = new URL(req.url, 'http://localhost');\n          const parts = url.pathname.slice(`${ROUTE_BASE}/jobs`.length).split('/').filter(Boolean);\n          if (req.method === 'GET' && parts.length === 0) {\n            // Machine-wide view: this hub's live jobs plus fresh shards from\n            // other writers (standalone MCP sessions, other hub instances).\n            const own = [...hub.jobs.values()].map((j) => ({ ...hub.view(j), origin: hub.shard.writer }));\n            const foreign = readMergedStatus({ excludeWriter: hub.shard.writer });\n            return sendJson(res, 200, { ok: true, jobs: [...own, ...foreign] });\n          }\n          if (req.method === 'GET' && parts.length === 1) {\n            const wait = parseWaitSeconds(url.searchParams.get('wait'));\n            if (wait === null) return sendJson(res, 400, { ok: false, error: 'wait must be a non-negative integer number of seconds' });\n            const job = await hub.wait(parts[0], Math.min(wait, 600) * 1000);\n            if (!job) return sendJson(res, 404, { ok: false, error: 'no such job' });\n            return sendJson(res, 200, { ok: true, job: hub.view(job, true) });\n          }\n          if (req.method === 'POST' && parts.length === 0) {\n            const payload = await readBody(req);\n            const job = await hub.spawn(payload);\n            return sendJson(res, 200, { ok: true, job: hub.view(job) });\n          }\n          if (req.method === 'POST' && parts.length === 2 && parts[1] === 'cancel') {\n            const job = await hub.cancel(parts[0]);\n            if (!job) return sendJson(res, 404, { ok: false, error: 'no such job' });\n            return sendJson(res, 200, { ok: true, job: hub.view(job, true) });\n          }\n          return sendJson(res, 404, { ok: false, error: 'unknown jobs endpoint' });\n        } catch (err) {\n          return sendJson(res, 400, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/config`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        try {\n          const { readGlobalConfig, writeGlobalConfig } = await import(`../install/install.mjs?t=${Date.now()}`);\n          if (req.method === 'GET') {\n            adoptLang(new URL(req.url, 'http://localhost').searchParams.get('lang'));\n            return sendJson(res, 200, { ok: true, config: readGlobalConfig() });\n          }\n          if (req.method === 'POST') return sendJson(res, 200, { ok: true, config: writeGlobalConfig(await readBody(req)) });\n          return sendJson(res, 405, { ok: false, error: 'GET or POST' }, { allow: 'GET, POST' });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/presets`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        try {\n          const presets = ctx.get('agentPresets');\n          if (presets === undefined) return sendJson(res, 200, { ok: true, presets: [] });\n          const list = await presets.list();\n          return sendJson(res, 200, {\n            ok: true,\n            defaultId: presets.defaultId,\n            presets: list.map((p) => ({ id: p.id, name: p.name ?? p.id, trust: p.trust })),\n          });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    // The MCP server runs as its own process and cannot reach ctx.llm, so the\n    // routes the HOST has configured are published here. This is the whole\n    // point of issue #10: a local model is configured once in DSH, and the\n    // worker config names it instead of redefining it.\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/providers`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        try {\n          const { readGlobalConfig } = await import('../install/install.mjs');\n          const providers = ctx.llm.listProviders().map((p) => ({ id: p.id, name: p.name ?? p.id }));\n          return sendJson(res, 200, {\n            ok: true,\n            providers,\n            bindings: describeBindings(readGlobalConfig()),\n          });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/vision-models`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        try {\n          const url = new URL(req.url, 'http://localhost');\n          const provider = url.searchParams.get('provider');\n          const force = url.searchParams.get('refresh') === '1';\n          const lang = url.searchParams.get('lang');\n          adoptLang(lang);\n          const { listVisionModels } = await import('../multimodal.mjs');\n          const { readGlobalConfig } = await import('../install/install.mjs');\n          return sendJson(res, 200, { ok: true, models: await listVisionModels(provider, force, () => readGlobalConfig(), lang) });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/provider-test`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'POST only' });\n        try {\n          // The entry comes from the panel form so unsaved edits can be probed.\n          const entry = await readBody(req);\n          adoptLang(entry?.lang);\n          const { testProvider } = await import('../multimodal.mjs');\n          const result = await testProvider(entry, entry?.lang);\n          return sendJson(res, 200, { ok: true, result });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/install/status`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        try {\n          const { installStatus } = await import(`../install/install.mjs?t=${Date.now()}`);\n          return sendJson(res, 200, { ok: true, status: installStatus() });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    disposers.push(webServer.register({\n      kind: 'exact', path: `${ROUTE_BASE}/install`,\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) return sendJson(res, 403, { ok: false, error: 'loopback only' });\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'POST only' }, { allow: 'POST' });\n        try {\n          const { target, statusline } = await readBody(req);\n          // Cache-busted import: the installer must always run the code\n          // currently on disk, not whatever this process first loaded —\n          // a stale cached copy once re-broke user settings after a fix.\n          const {\n            installClaudeCode, installCodex, installHudSegment, uninstallClaudeCode, uninstallCodex,\n            installAgy, installGrok, uninstallAgy, uninstallGrok,\n          } = await import(`../install/install.mjs?t=${Date.now()}`);\n          if (target === 'claude') {\n            const base = await installClaudeCode({ statusline: !!statusline });\n            const hud = installHudSegment({});\n            return sendJson(res, 200, {\n              ok: base.ok,\n              actions: [...base.actions, ...hud.actions.map((a) => `hud: ${a}`)],\n            });\n          }\n          if (target === 'codex') return sendJson(res, 200, installCodex({}));\n          if (target === 'agy') return sendJson(res, 200, installAgy({}));\n          if (target === 'grok') return sendJson(res, 200, installGrok({}));\n          if (target === 'claude-uninstall') return sendJson(res, 200, await uninstallClaudeCode({}));\n          if (target === 'codex-uninstall') return sendJson(res, 200, uninstallCodex({}));\n          if (target === 'agy-uninstall') return sendJson(res, 200, uninstallAgy({}));\n          if (target === 'grok-uninstall') return sendJson(res, 200, uninstallGrok({}));\n          return sendJson(res, 400, { ok: false, error: 'target must be claude | codex | agy | grok | claude-uninstall | codex-uninstall | agy-uninstall | grok-uninstall' });\n        } catch (err) {\n          return sendJson(res, 500, { ok: false, error: err?.message ?? String(err) });\n        }\n      },\n    }));\n\n    return () => { for (const d of disposers.reverse()) d(); };\n  });\n\n  ctx.logger?.info?.('dsh-crew hub mounted (jobs API + installer endpoints + multimodal tools)');\n  return async () => {\n    for (const d of disposers.reverse()) { try { d(); } catch {} }\n    await hub.dispose();\n  };\n}\n"
